## 5. **完整的调度方案示例**

```javascript
// advanced-scheduler.js
const schedule = require('node-schedule');
const { exec } = require('child_process');
const fs = require('fs');
const path = require('path');

class PlaywrightScheduler {
  constructor(config) {
    this.config = {
      cronExpression: '0 2 * * *', // 默认每天凌晨2点
      testCommand: 'npx playwright test',
      reportDir: './playwright-reports',
      ...config
    };
  }

  async runTests() {
    const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
    const reportFile = path.join(this.config.reportDir, `report-${timestamp}.html`);

    return new Promise((resolve, reject) => {
      exec(`${this.config.testCommand} --reporter=html`, (error, stdout, stderr) => {
        if (error) {
          console.error('测试失败:', error);
          this.saveReport(reportFile, { error: error.message, stderr });
          reject(error);
        } else {
          console.log('测试成功完成');
          this.saveReport(reportFile, { success: true, stdout });
          resolve(stdout);
        }
      });
    });
  }

  saveReport(filePath, data) {
    // 确保报告目录存在
    if (!fs.existsSync(this.config.reportDir)) {
      fs.mkdirSync(this.config.reportDir, { recursive: true });
    }

    // 保存报告
    fs.writeFileSync(filePath, JSON.stringify(data, null, 2));
    console.log(`报告已保存到: ${filePath}`);
  }

  start() {
    console.log(`启动Playwright测试调度器，计划: ${this.config.cronExpression}`);

    schedule.scheduleJob(this.config.cronExpression, async () => {
      console.log('开始执行计划测试...');
      try {
        await this.runTests();
        console.log('计划测试执行完成');
      } catch (error) {
        console.error('计划测试执行失败:', error);
      }
    });
  }
}

// 使用示例
const scheduler = new PlaywrightScheduler({
  cronExpression: '0 */6 * * *', // 每6小时运行一次
  testCommand: 'npx playwright test --grep @smoke' // 只运行冒烟测试
});

scheduler.start();
```

